export const BRUTO: Bruto[] = [
  [1, "", 1, "pt", "Significação das palavras", [0, 1], "A forma verbal “viceja” (ℓ.1) poderia ser substituída por germina, sem prejuízo da coerência e da correção gramatical do trecho.", "C", "“Viceja” vem de vicejar: desenvolver-se com vigor, brotar. “Germina” (de germinar: brotar, começar a se desenvolver) mantém o sentido figurado da frase e também não pede complemento. A troca fica coerente e correta.", ""],
  [2, "", 1, "pt", "Compreensão de texto", [0, 1], "Infere-se do primeiro parágrafo do texto que “boêmios da pá virada e vampiros” diferem biologicamente dos seres humanos em geral, os quais tendem a desempenhar a maior parte de suas atividades durante a manhã e a tarde.", "E", "O trecho é humorístico: “boêmios da pá virada e vampiros” são apresentados como gente de hábitos noturnos. O texto não diz que eles diferem biologicamente dos outros seres humanos.", ""],
  [4, "", 1, "pt", "Expressão de realce", [0, 1], "A correção gramatical e os sentidos do texto seriam mantidos caso se suprimisse o trecho “é que”, em “como é que se fazia” (ℓ.27).", "C", "Em “como é que se fazia”, o “é que” é só de realce (expletivo). Sem ele, “como se fazia” mantém a correção e o sentido da pergunta.", ""],
  [5, "", 1, "pt", "Crase", [0, 1], "Sem prejuízo da correção gramatical e dos sentidos do texto, o primeiro período do terceiro parágrafo poderia ser assim reescrito: Contudo, os cientistas avisam que ter tanta luz à nosso dispor custa muito caro ao meio ambiente.", "E", "Não há crase antes de pronome possessivo masculino: o certo é “a nosso dispor”. Com “à nosso dispor”, a reescrita fica errada.", ""],
  [6, "", 1, "pt", "Pontuação e orações adjetivas", [0, 1], "A correção gramatical do texto seria mantida, mas seu sentido seria alterado, caso o trecho “que se infiltra no ambiente no qual dormimos” (ℓ. 18 e 19) fosse isolado por vírgulas.", "C", "Entre vírgulas, a oração “que se infiltra no ambiente no qual dormimos” deixa de ser restritiva e passa a ser explicativa. O trecho continua correto, mas o sentido muda: em vez de delimitar de que luz se fala, a oração passa a comentar toda a luz citada.", ""],
  [7, "", 1, "pt", "Correlação verbal", [0, 1], "A correção gramatical e os sentidos do texto seriam mantidos caso a forma verbal “existia” (ℓ.34) fosse substituída por existisse.", "E", "“Se existia, já foi extinto” combina indicativo com indicativo. Com “se existisse” (hipótese no subjuntivo), a outra oração teria de ir para o futuro do pretérito (“já teria sido extinto”). Só trocar “existia” quebra a correlação e muda o sentido.", ""],
  [8, "", 1, "pt", "Pronome indefinido", [0, 1], "A substituição da locução “a cidade toda” (ℓ.30) por toda cidade preservaria os sentidos e a correção gramatical do período.", "E", "“A cidade toda” é a cidade inteira, uma só. “Toda cidade”, sem artigo, quer dizer qualquer cidade. O sentido muda.", ""],
  [9, "", 1, "pt", "Compreensão de texto", [0, 1], "É correto inferir do trecho “o homem da luz já deve ter se transferido para o mundo das trevas eternas” (ℓ. 34 e 35) que provavelmente o funcionário responsável pelo acionamento da iluminação urbana já morreu.", "C", "“Mundo das trevas eternas” é um modo indireto (eufemismo) de falar da morte, e “deve ter” indica probabilidade. Logo, é correto inferir que o funcionário que acendia a iluminação provavelmente já morreu.", ""],
  [10, "", 1, "pt", "Coesão (pronomes)", [2, 3], "As formas pronominais “Estas” (ℓ.4) e “las” (ℓ.7) referem-se a “necessidades dos seres humanos” (ℓ. 2 e 3).", "C", "“Estas” e o pronome “las” retomam “necessidades dos seres humanos”: são elas que o trabalho busca satisfazer.", ""],
  [11, "", 1, "pt", "Reescrita (sentido)", [2, 3], "Seriam mantidos os sentidos do texto caso o primeiro período do segundo parágrafo fosse assim reescrito: Quando prestamos atenção a nossa volta, percebemos que quase tudo que vemos existe pelas atividades do trabalho humano.", "E", "No original, “Se prestarmos atenção… perceberemos” expressa condição, com o verbo no futuro. A reescrita com “Quando prestamos… percebemos” passa a expressar tempo e fato habitual, no presente. O sentido muda.", ""],
  [12, "", 1, "pt", "Conectivos", [2, 3], "A locução “em razão de” (ℓ.9) expressa uma ideia de causa.", "C", "“Em razão de” equivale a “por causa de”: introduz a causa.", ""],
  [13, "", 1, "pt", "Conectivos", [2, 3], "Com o emprego da expressão “assim como” (ℓ.12), estabelece-se uma relação de comparação entre ideias expressas no período.", "C", "“Assim como” liga as ideias por comparação, aproximando os dois termos. Foi o que a banca confirmou.", ""],
  [14, "", 1, "pt", "Compreensão de texto", [2, 3], "Conclui-se do texto que, devido à abundância de recursos, nas sociedades tribais os indivíduos não têm necessidade de separar as práticas laborais das outras atividades sociais.", "E", "O texto não liga a forma de trabalho das sociedades tribais à abundância de recursos. Essa relação de causa foi inventada pelo item.", ""],
  [15, "", 1, "pt", "Pontuação", [2, 3], "Caso o advérbio “praticamente” (ℓ.23) fosse isolado por vírgulas, a correção gramatical do trecho seria alterada.", "E", "As vírgulas que isolariam o advérbio “praticamente” são opcionais: o trecho continuaria correto. Por isso o item, que fala em alterar a correção, está errado.", ""],
  [16, "", 1, "pt", "Sintaxe (sujeito)", [2, 3], "No trecho “Os processos de produção dos objetos que nos cercam movimentam relações diversas entre os indivíduos” (ℓ. 10 a 12), o sujeito da forma verbal “cercam” é “Os processos de produção dos objetos”.", "E", "O sujeito de “cercam” é o pronome relativo “que”, que retoma “objetos”: são os objetos que nos cercam. “Os processos de produção dos objetos” é o sujeito de “movimentam”.", ""],
  [17, "", 1, "pt", "Compreensão de texto", [4, 5], "A afirmação de que alguns nomes põem nos olhos de seus donos “um azul que não possuem” (ℓ. 4 e 5) contradiz a ideia de que os nomes definem não as qualidades reais de cada um, mas o modo como os outros o veem.", "E", "Dizer que um nome põe nos olhos de alguém “um azul que não possuem” é justamente mostrar que o nome cria uma imagem, e não as qualidades reais. O trecho confirma a ideia, não a contradiz.", ""],
  [18, "", 1, "pt", "Compreensão de texto", [4, 5], "A informação apresentada pela oração “nenhuma letra se igualando a outra” (ℓ. 7 e 8) é redundante em relação à informação apresentada na oração imediatamente anterior, servindo para reforçar-lhe o sentido.", "C", "“Nenhuma letra se igualando a outra” repete, com outras palavras, a ideia da oração anterior sobre nomes diferentes entre si. A repetição serve para reforçar o sentido.", ""],
  [19, "", 1, "pt", "Coesão (referência)", [4, 5], "O vocábulo “um” (ℓ.14) refere-se a um indivíduo cujo nome é idêntico ao do autor do texto.", "C", "“Um” retoma, por elipse, “um homônimo”: outra pessoa com o mesmo nome do autor, que é o assunto do texto.", ""],
  [20, "", 1, "pt", "Compreensão de texto", [4, 5], "Infere-se que o autor do texto é espanhol.", "E", "O texto fala do nome do autor e de um homônimo, mas em nenhum momento diz que o autor é espanhol. A inferência não tem apoio no texto.", ""],
  [21, "", 1, "rlm", "Sequências", [6, 7], "O padrão apresentado pela referida sequência indica que os números podem corresponder, na ordem em que aparecem, a ordenadas de pontos do gráfico de uma função afim de inclinação positiva.", "E", "A sequência sobe e desce (25, 75, 50, 150, 100…): de 75 vai para 50, por exemplo. Uma função afim de inclinação positiva é sempre crescente, então não pode gerar esses valores na ordem dada.", ""],
  [22, "", 1, "rlm", "Sequências", [6, 7], "A partir do padrão da sequência, infere-se que o 12.º termo é o número 1.600.", "E", "Os termos de ordem par são 75, 150, 300, 600, 1.200, 2.400 (cada um é o dobro do anterior). O 12.º termo é o 6.º da lista dos pares: 2.400, e não 1.600.", ""],
  [23, "", 1, "rlm", "Sequências", [6, 7], "Se a(n) for o n-ésimo termo da sequência, em que n = 1, 2, 3, ..., então, para n ≥ 3, tem-se que a(n) = 2 × a(n – 2).", "C", "Cada termo é o dobro do termo que está duas posições antes: 50 = 2 × 25, 150 = 2 × 75, 100 = 2 × 50, 300 = 2 × 150. Logo, a(n) = 2 × a(n – 2) para n ≥ 3.", ""],
  [27, "", 1, "rlm", "Função exponencial", [8, 9], "Segundo o modelo apresentado, após dez anos de campanha educativa, haverá, em cada um dos anos seguintes, menos de 300 acidentes de trânsito com vítimas fatais.", "E", "Como e^(–x) é sempre positivo, f(x) = 350 + 150·e^(–x) é sempre maior que 350. Nunca haverá menos de 300 acidentes no modelo.", ""],
  [28, "", 1, "rlm", "Função exponencial", [8, 9], "De acordo com o modelo, no final do primeiro ano da campanha, apesar do decréscimo com relação ao ano anterior, ainda ocorreram mais de 400 acidentes de trânsito com vítimas fatais.", "C", "No início, f(0) = 350 + 150 = 500. Ao fim do primeiro ano, f(1) = 350 + 150/e ≈ 350 + 55 = 405. Houve queda, mas ainda são mais de 400 acidentes.", ""],
  [29, "", 1, "info", "Navegadores e protocolos", [10], "As versões mais modernas dos navegadores Chrome, Firefox e Edge reconhecem e suportam, em instalação padrão, os protocolos de Internet FTP, SMTP e NNTP, os quais implementam, respectivamente, aplicações de transferência de arquivos, correio eletrônico e compartilhamento de notícias.", "E", "Os navegadores não trazem suporte a SMTP (envio de e-mail) nem a NNTP (notícias): isso fica com programas de e-mail e leitores de notícias. Hoje nem o FTP é aceito: Chrome e Firefox o retiraram em 2021.", ""],
  [30, "", 1, "info", "Acesso remoto", [10], "Por meio de uma aplicação de acesso remoto, um computador é capaz de acessar e controlar outro computador, independentemente da distância física entre eles, desde que ambos os computadores estejam conectados à Internet.", "C", "Com um programa de acesso remoto, um computador controla outro pela internet, a qualquer distância, desde que os dois estejam conectados.", ""],
  [32, "", 1, "info", "Malware (vírus de script)", [11], "No acesso a uma página web que contenha o código de um vírus de script, pode ocorrer a execução automática desse vírus, conforme as configurações do navegador.", "C", "O vírus de script vem embutido na página (em JavaScript, por exemplo) e pode rodar sozinho quando a página abre, dependendo das configurações de segurança do navegador.", ""],
  [34, "", 1, "info", "Computação em nuvem", [12], "A computação em nuvem do tipo software as a service (SaaS) possibilita que o usuário acesse aplicativos e serviços de qualquer local usando um computador conectado à Internet.", "C", "No SaaS (software como serviço), o programa roda no provedor e o usuário o usa pela internet, de qualquer lugar, sem instalar nada.", ""],
  [35, "", 1, "fisica", "Lançamento horizontal", [13, 14], "O deslocamento do projétil na direção horizontal ocorre de acordo com uma função quadrática do tempo.", "E", "Na horizontal não há aceleração (o atrito do ar é desprezado): o movimento é uniforme, x = v·t, uma função do 1.º grau. A função quadrática do tempo é a da queda, na vertical.", ""],
  [36, "", 1, "fisica", "Lançamento horizontal", [13, 14], "Na situação em tela, o projétil atingirá o alvo circular.", "E", "720 km/h = 200 m/s. Para andar 50 m, o projétil leva 50 ÷ 200 = 0,25 s. Nesse tempo ele cai h = 9,8 × 0,25² ÷ 2 ≈ 0,31 m, ou 31 cm. O alvo tem 10 cm de raio, então o projétil passa abaixo dele.", ""],
  [37, "", 1, "fisica", "Trabalho do peso", [13, 14], "Se o alvo fosse retirado da direção do projétil, então o trabalho realizado pela força gravitacional para levar o projétil até o solo seria superior a 0,10 J.", "C", "Trabalho do peso = m·g·h = 0,015 × 9,8 × 1,5 ≈ 0,22 J, maior que 0,10 J.", ""],
  [38, "", 1, "fisica", "Movimento circular", [15, 16], "O veículo está sujeito a uma aceleração centrípeta superior à aceleração gravitacional.", "E", "54 km/h = 15 m/s. A aceleração centrípeta é v²/R = 225 ÷ 50 = 4,5 m/s², menor que 9,8 m/s².", ""],
  [39, "", 1, "fisica", "Movimento circular e atrito", [15, 16], "Se o veículo estivesse sujeito a uma aceleração centrípeta de 4,8 m/s², então ele faria a curva em segurança, sem derrapar.", "C", "O atrito garante no máximo μ·g = 0,60 × 9,8 = 5,88 m/s² de aceleração centrípeta. Como 4,8 m/s² é menor que esse limite, o carro faz a curva sem derrapar.", ""],
  [40, "", 1, "fisica", "Quantidade de movimento", [15, 16], "Considere que esse veículo colida com outro veículo, mas o sistema permaneça isolado, ou seja, não haja troca de matéria com o meio externo nem existam forças externas agindo sobre ele. Nesse caso, segundo a lei de conservação da quantidade de movimento, a soma das quantidades de movimento dos dois veículos, antes e após a colisão, permanece constante.", "C", "Num sistema isolado, sem forças externas, a quantidade de movimento total se conserva: a soma é a mesma antes e depois da colisão.", ""],
  [41, "", 1, "etica", "Código de Ética (Decreto 1.171/1994)", [17], "Na administração pública, moralidade restringe-se à distinção entre o bem e o mal: o servidor público nunca poderá desprezar o elemento ético de sua conduta.", "E", "Pelas regras do Código, a moralidade não se resume à distinção entre o bem e o mal: o fim da conduta é sempre o bem comum. O erro está em “restringe-se”.", ""],
  [42, "", 1, "etica", "Código de Ética (Decreto 1.171/1994)", [17], "No estrito exercício de sua função, o servidor público deve nortear-se por primados maiores — como a consciência dos princípios morais, o zelo e a eficácia —; fora dessa função, porém, por estar diante de situação particular, não está obrigado a agir conforme tais primados.", "E", "O Código diz que o servidor deve se guiar pela dignidade, decoro, zelo, eficácia e consciência dos princípios morais tanto no cargo quanto fora dele. Não há folga na vida particular.", ""],
  [43, "", 1, "etica", "Código de Ética (Decreto 1.171/1994)", [17], "Servidor público que se apresenta habitualmente embriagado no serviço ou até mesmo fora dele poderá ser submetido à Comissão de Ética, a qual poderá aplicar-lhe a pena de censura.", "C", "Apresentar-se embriagado no serviço, ou fora dele de forma habitual, é vedado pelo Código. A pena que a Comissão de Ética aplica é a de censura.", ""],
  [44, "", 1, "etica", "Código de Ética (Decreto 1.171/1994)", [17], "Servidor público que, no exercício da função pública, desviar outro servidor para atender a seu interesse particular, ou, movido pelo espírito de solidariedade, for conivente com prática como esta, poderá ser submetido à Comissão de Ética.", "C", "As duas condutas estão entre as vedações do Código: desviar servidor para atender interesse particular e ser conivente com erro ou infração por espírito de solidariedade. Ambas podem levar o caso à Comissão de Ética.", ""],
  [45, "", 1, "geopolitica", "Transportes e economia", [18, 19], "O custo do frete e as grandes distâncias a serem percorridas entre as regiões produtoras e os centros urbanos consumidores e os portos de exportação são fatores que impactam diretamente no preço dos produtos agropecuários e industriais brasileiros e em sua competividade nos mercados nacional e internacional.", "C", "Com a dependência das rodovias e as longas distâncias até cidades e portos, o frete pesa no custo final. Isso encarece os produtos e tira competitividade dentro e fora do país.", ""],
  [46, "", 1, "geopolitica", "Transportes e economia", [18, 19], "A rede de transporte rodoviário integra todo o território brasileiro, com rodovias conectando em rede todos os municípios das cinco macrorregiões do território nacional, e a predominância desse modal de transporte é fator de vulnerabilidade em relação aos países desenvolvidos, os quais também dependem desse modal de transporte.", "E", "A rede rodoviária não liga todos os municípios: na Amazônia muitos dependem de rios ou de avião. E os países desenvolvidos diversificam os modais (o Canadá tem 8% nas rodovias, segundo o próprio texto).", ""],
  [47, "", 1, "geopolitica", "Globalização e território", [20, 21], "O processo de globalização econômica e desenvolvimento tecnológico é marcado pela solidariedade organizacional entre empresas, sistema financeiro, tecnologia e lugares eleitos como regiões de investimento pela economia globalizada e, com o capital globalizado, busca-se desenvolver as regiões de modo a diminuir as desigualdades regionais e a oferecer uma economia justa e solidária.", "E", "A globalização escolhe lugares para investir e deixa outros de fora. Em vez de diminuir, ela tende a aprofundar as desigualdades regionais. Não busca uma economia “justa e solidária”.", ""],
  [48, "", 1, "geopolitica", "Economia brasileira", [20, 21], "No Brasil, o setor de serviços ampliou a sua participação no PIB; o setor agropecuário, estratégico na economia brasileira, se tornou mais complexo, o que permitiu a ampliação de diversos serviços relacionados aos diferentes momentos do processo de produção/consumo, como os setores de tecnologia, transporte e finanças.", "C", "Os serviços são a maior parte do PIB brasileiro, e a modernização do agro puxou serviços ligados a ele, como tecnologia, transporte e finanças.", ""],
  [49, "", 1, "carreira", "História e atuação da PRF", [22], "Durante os grandes eventos esportivos sediados no Brasil nesta década, a PRF adotou como principal estratégia concentrar suas ações de policiamento nos locais de realização dos eventos, priorizando a segurança dos estrangeiros que ingressaram no país, especialmente de autoridades e delegações esportivas, com destaque para as atividades de escolta.", "E", "Nos grandes eventos (Copa de 2014, Olimpíada de 2016), a PRF atuou principalmente nas rodovias federais: fluxo de torcedores, fiscalização e escoltas. Ela não concentrou o policiamento nos locais dos jogos.", ""],
  [50, "", 1, "carreira", "História e atuação da PRF", [22], "No que se refere ao trânsito, a PRF exerce atividades como fiscalização de documentos e repressão a modalidades criminosas, além de atividades educativas para adultos e crianças, por meio de projetos que visem transmitir aspectos legais, éticos e de cidadania.", "C", "Além de fiscalizar e combater o crime, a PRF faz educação para o trânsito, com projetos para adultos e crianças sobre aspectos legais, éticos e de cidadania.", ""],
  [51, "", 2, "transito", "Crimes de trânsito (racha)", [23, 24], "Godofredo e Antônio responderiam por crime de trânsito independentemente da lesão corporal causada, pois a conduta de ambos gerou situação de risco à incolumidade pública.", "C", "O racha (art. 308 do CTB) é crime de perigo concreto: basta gerar situação de risco à incolumidade pública. Não precisa haver lesão.", ""],
  [52, "", 2, "transito", "Crimes de trânsito (racha)", [23, 24], "Godofredo e Antônio estão sujeitos à pena de reclusão, em razão do resultado danoso da conduta delitiva narrada.", "C", "Se do racha resulta lesão corporal grave, e as circunstâncias mostram que o agente não quis o resultado nem assumiu o risco, a pena é de reclusão de 3 a 6 anos (art. 308, § 1.º).", ""],
  [53, "", 2, "transito", "Crimes de trânsito (disposições gerais)", [23, 24], "Por se tratar de lesão corporal de natureza culposa, é vedada a instauração de inquérito policial para apurar as condutas de Godofredo e Antônio, bastando a realização dos exames médicos da vítima e o compromisso dos autores em comparecer a todos os atos necessários junto às autoridades policial e judiciária.", "E", "Na lesão culposa cometida durante racha, não se aplicam os benefícios da Lei 9.099/1995 (art. 291, § 1.º, II), e o CTB manda instaurar inquérito policial (art. 291, § 2.º).", ""],
  [54, "", 2, "transito", "Crimes de trânsito (omissão de socorro)", [25], "Dirigindo seu veículo automotor, Luciano atropelou um transeunte, causando-lhe ferimentos leves. Luciano não prestou socorro à vítima nem solicitou auxílio da autoridade pública. Nessa situação, a conduta de Luciano será considerada atípica caso um terceiro tenha prestado apoio à vítima em seu lugar.", "E", "A omissão de socorro é punida mesmo que um terceiro socorra a vítima (art. 304, parágrafo único). Como foi Luciano quem causou a lesão, ele responde pela lesão culposa no trânsito (art. 303) com a pena aumentada por não prestar socorro. A conduta não é atípica.", ""],
  [55, "", 2, "transito", "Crimes de trânsito (violação da suspensão)", [25], "Felipe, ao violar a suspensão para dirigir, foi flagrado e autuado pela autoridade competente, em operação de fiscalização, conduzindo seu veículo automotor em via pública. Nessa situação, Felipe responderá por crime de trânsito e poderá receber como pena nova imposição adicional de suspensão pelo dobro do primeiro prazo, sendo vedada a substituição de pena privativa de liberdade por restritiva de direito, em razão da natureza da infração.", "E", "Violar a suspensão é crime (art. 307), e a pena traz nova suspensão por prazo idêntico ao da anterior, não pelo dobro. Também não há vedação legal à troca por pena restritiva de direitos (o art. 312-A até indica quais servem).", ""],
  [56, "", 2, "transito", "Crimes de trânsito (homicídio culposo)", [25], "Lucas, motorista de ônibus, quando dirigia seu coletivo, atropelou e matou, culposamente, uma pedestre. Sávio, ao conduzir seu veículo em um passeio com a família, atropelou culposamente, na faixa de pedestre, uma pessoa, que faleceu no mesmo instante. Severino, ao dirigir seu veículo, atropelou culposamente uma transeunte que estava na calçada; ela morreu em seguida. Nessas situações, Lucas, Sávio e Severino responderão por crime de trânsito, cujas penas poderão, pelas circunstâncias fáticas, ser aumentadas até a metade, e suas habilitações para dirigir deverão ser suspensas.", "C", "Os três respondem por homicídio culposo na direção (art. 302), que já traz a suspensão ou proibição de dirigir. A pena aumenta de 1/3 até a metade se o fato ocorre na faixa de pedestres ou na calçada (Sávio e Severino) ou se o motorista transporta passageiros na sua profissão (Lucas), conforme o § 1.º.", ""],
  [57, "", 2, "transito", "Crimes de trânsito (agravantes)", [25], "Alfredo, conduzindo seu veículo automotor sem placas, atropelou um pedestre. Alessandro, dirigindo um veículo de categoria diversa das que sua carteira de habilitação permitia, causou lesão corporal culposa em um transeunte, ao atingi-lo. Nessas situações, as penas impostas a Alfredo e a Alessandro serão agravadas, devendo o juiz aplicar as penas-base com especial atenção à culpabilidade e às circunstâncias e consequências do crime.", "C", "Dirigir veículo sem placas e com habilitação de categoria diferente são agravantes do art. 298 (incisos II e IV). E o art. 291, § 4.º, manda o juiz fixar a pena-base com especial atenção à culpabilidade e às circunstâncias e consequências do crime.", ""],
  [58, "", 2, "transito", "Crimes de trânsito (entregar a direção)", [26, 27], "Sandro responderá por crime de trânsito somente se a condução de Wellington causar perigo de dano.", "E", "Entregar a direção a pessoa não habilitada (art. 310) é crime de perigo abstrato: não precisa haver perigo de dano (Súmula 575 do STJ).", ""],
  [59, "", 2, "transito", "Crimes de trânsito (dirigir sem habilitação)", [26, 27], "Wellington responderá por crime de trânsito, independentemente de gerar perigo de dano ao conduzir o veículo.", "E", "Dirigir sem habilitação só é crime (art. 309) se gerar perigo de dano. Sem perigo, é apenas infração administrativa (art. 162, I).", ""],
  [60, "", 2, "transito", "Infrações (habilitação)", [28], "Dirigindo seu veículo automotor, Caio foi abordado por policial rodoviário federal, que constatou que a validade de sua carteira nacional de habilitação estava vencida havia mais de trinta dias. Nessa situação, Caio será multado, sua carteira de habilitação será recolhida e seu veículo será removido.", "E", "CNH vencida há mais de 30 dias é infração gravíssima (art. 162, V), com multa e retenção do veículo até aparecer um condutor habilitado. O veículo não é removido.", "Na época da prova, a CNH também era recolhida. Na redação atual do art. 162, V, a medida é só a retenção do veículo. O item continua errado por causa da remoção."],
  [63, "", 2, "transito", "Infrações (estacionamento)", [28], "O condutor estacionou o seu veículo sem observar a distância máxima permitida de afastamento da guia da calçada. Nessa situação, o condutor poderá ser multado e seu veículo, removido.", "C", "Estacionar afastado da guia da calçada de 50 cm a 1 m é infração leve, e a mais de 1 m é grave (art. 181, II e III). Nos dois casos há multa e remoção do veículo.", ""],
  [64, "", 2, "transito", "Infrações (fumaça)", [28], "Márcio conduzia seu veículo automotor produzindo fumaça em níveis superiores aos legalmente permitidos. Nessa situação, conforme o nível de fumaça exalada, a conduta de Márcio pode configurar tanto infração administrativa como crime de trânsito.", "E", "Rodar soltando fumaça acima dos níveis do CONTRAN é infração grave, com multa e retenção para regularização (art. 231, III). Não existe crime de trânsito para essa conduta, seja qual for o nível.", ""],
  [65, "", 2, "transito", "Pontuação", [29], "Para que uma concessionária de serviço público de transporte de passageiros conheça a pontuação de infrações atribuída a um motorista de seu quadro funcional, que, no exercício da atividade remunerada ao volante, tenha tido seu direito de dirigir suspenso, ela deve ter autorização do respectivo empregado, uma vez que essa informação é personalíssima.", "E", "O CTB (art. 261) garante à concessionária ou permissionária de serviço público o direito de saber os pontos dos motoristas do seu quadro que dirigem profissionalmente, na forma do CONTRAN. Não precisa de autorização do empregado.", ""],
  [66, "", 2, "transito", "Multas (veículo estrangeiro)", [29], "Se um policial rodoviário federal autuar, por infração de trânsito, um condutor de veículo em circulação no Brasil, mas licenciado no exterior, o infrator deverá pagar a multa no país de origem do licenciamento do automóvel, na forma estabelecida pelo CONTRAN.", "E", "Veículo licenciado no exterior paga a multa antes de sair do país, respeitada a reciprocidade (art. 260, § 4.º). A cobrança não fica para o licenciamento.", ""],
  [67, "", 2, "transito", "Velocidade máxima", [30], "Nas rodovias de pista dupla localizadas em vias rurais, a velocidade máxima permitida para automóveis, camionetas e motocicletas será a mesma.", "C", "Nas rodovias de pista dupla, o limite é de 110 km/h para automóveis, camionetas, caminhonetes e motocicletas (art. 61, § 1.º, II, a).", ""],
  [68, "", 2, "transito", "Sinalização (prevalência)", [30], "A sinalização de trânsito segue uma ordem de prevalência: as ordens do agente de trânsito prevalecem sobre as normas de circulação e outros sinais; as indicações do semáforo sobre os demais sinais; e as indicações dos sinais sobre as demais normas de trânsito.", "C", "A ordem do art. 89 é: ordens do agente sobre as normas de circulação e os outros sinais; semáforo sobre os demais sinais; sinais sobre as demais normas de trânsito.", ""],
  [69, "", 2, "transito", "Sistema Nacional de Trânsito", [31], "A Polícia Rodoviária Federal integra o Sistema Nacional de Trânsito, competindo-lhe, no âmbito das rodovias e estradas federais, implementar as medidas da Política Nacional de Segurança e Educação de Trânsito.", "C", "A PRF integra o SNT (art. 7.º) e, nas rodovias federais, implementa as medidas da Política Nacional de Segurança e Educação de Trânsito (art. 20, VIII).", ""],
  [70, "", 2, "transito", "Sistema Nacional de Trânsito", [31], "O CONTRAN é o órgão máximo executivo de trânsito da União, cabendo a coordenação máxima do Sistema Nacional de Trânsito ao Departamento Nacional de Trânsito (DENATRAN).", "E", "O CONTRAN é o coordenador do sistema e o órgão máximo normativo e consultivo (art. 7.º, I). O órgão máximo executivo de trânsito da União é outro (art. 19).", "Desde 2021 (Decreto 10.788/2021), o antigo DENATRAN se chama Secretaria Nacional de Trânsito (SENATRAN)."],
  [71, "", 2, "transito", "Fiscalização (álcool)", [32], "Em uma operação de fiscalização, na abordagem de um veículo automotor, o policial rodoviário federal, ao notar que o condutor do veículo apresentava vermelhidão nos olhos, odor de álcool no hálito, desordem nas vestes e fala alterada, solicitou que o motorista se submetesse ao competente teste, mas o etilômetro apresentou súbita pane, tornando-se inservível para o teste. Nessa situação, diante da impossibilidade de confirmar alteração da capacidade psicomotora do condutor, o policial ficou impedido de lavrar o auto de infração pela conduta de direção sob a influência de álcool prevista no CTB.", "E", "Sem o etilômetro, a infração pode ser provada de outros modos: sinais de alteração da capacidade psicomotora, imagem, vídeo e outras provas admitidas (art. 277, § 2.º). Olhos vermelhos, hálito de álcool e fala alterada bastam para o auto.", ""],
  [74, "", 2, "transito", "Fiscalização de velocidade", [32], "Em uma rodovia federal, em um trecho em curva localizado fora do perímetro urbano, é alto o índice de acidentes de trânsito, apesar de haver medidor de velocidade do tipo fixo instalado no local. Nesse caso, no sentido de aumentar a fiscalização do excesso de velocidade nesse trecho, será correta a utilização de equipamento do tipo portátil à distância de um quilômetro do medidor de velocidade do tipo fixo já instalado.", "E", "Medidor portátil só pode ficar a pelo menos 500 m de um fixo em vias urbanas (e trechos rurais com características urbanas) e a pelo menos 2 km nos demais trechos rurais. Numa curva fora da área urbana, 1 km não basta.", "A norma da época (Resolução CONTRAN 396/2011) foi substituída pela Resolução 798/2020, e a resposta continua a mesma."],
  [76, "", 2, "transito", "Transporte de bicicletas", [33], "Não se permite o transporte de bicicleta em veículo com o compartimento de carga aberto, mesmo que o comprimento da bicicleta ultrapasse o comprimento da caçamba ou do referido compartimento.", "E", "A bicicleta conta como carga indivisível, e se pode circular com a caçamba ou o compartimento aberto quando a carga indivisível passa do seu comprimento (Resolução CONTRAN 955/2022). Logo, é permitido.", "Na época da prova valia a Resolução 349/2010, hoje revogada pela Resolução 955/2022. A resposta continua a mesma."],
  [77, "", 2, "transito", "Transporte de bicicletas", [33], "Independentemente de instruções do fabricante, nos dispositivos instalados na parte traseira externa do veículo, a quantidade de bicicletas que podem ser transportadas depende do comprimento do balanço traseiro ocupado pelas bicicletas, que, de acordo com a legislação pertinente, não pode ultrapassar 60% da distância entre os eixos do veículo transportador.", "E", "Nos dispositivos de transporte de bicicletas, valem as especificações do fabricante, inclusive o número máximo de bicicletas (Resolução CONTRAN 955/2022). O “independentemente de instruções do fabricante” torna o item errado.", "Na época da prova valia a Resolução 349/2010, hoje revogada pela Resolução 955/2022."],
  [78, "", 2, "transito", "Transporte de bicicletas", [33], "O transporte de bicicletas em dispositivos fixados no teto de veículos estará em conformidade com a legislação de trânsito caso a altura do sistema veículo-dispositivo-bicicletas não ultrapasse 4,4 metros.", "C", "No teto, o conjunto veículo-dispositivo-bicicletas deve respeitar as dimensões máximas da norma de pesos e dimensões, cuja altura máxima é 4,40 m. Até 4,4 m, o transporte está regular.", "Na época da prova valia a Resolução 349/2010, hoje revogada pela Resolução 955/2022."],
  [79, "", 2, "transito", "Tempo de direção", [34, 35], "O condutor em questão não ultrapassou o tempo máximo ininterrupto de direção previsto na legislação de trânsito para o tipo de veículo referido.", "C", "O motorista profissional não pode dirigir mais de 5h30 ininterruptas (art. 67-C). Ele saiu às 17h e foi abordado às 21h: 4 horas de direção.", ""],
  [80, "", 2, "transito", "Infrações (registrador)", [34, 35], "Nessa situação, apesar de o disco-diagrama não se prestar para exame, não cabe a aplicação de penalidade decorrente do defeito no aparelho registrador, já que foi possível a fiscalização do tempo de direção do motorista por meio da verificação da ficha de trabalho do autônomo.", "E", "Registrador instantâneo de velocidade e tempo viciado ou defeituoso é infração própria (art. 230, XIV: grave, multa e retenção). A ficha de trabalho não afasta essa infração.", ""],
  [81, "", 2, "transito", "Veículos com dimensões excedentes", [34, 35], "Haja vista o horário e o local da vistoria, bem como as condições de transporte do veículo, o policial rodoviário federal deverá lavrar auto de infração pelo descumprimento da restrição de tráfego, cabendo a aplicação de penalidades previstas no CTB.", "C", "Uma combinação de 22 m precisa de autorização especial, que só permite trafegar no período do amanhecer ao pôr do sol. À noite, em pista simples, só em casos especiais justificados. Às 21h, fora do que a autorização permite, cabe auto de infração e as penalidades do CTB.", "Na época valiam as Resoluções 210 e 211/2006, hoje substituídas pela Resolução CONTRAN 882/2021. A resposta continua a mesma."],
  [82, "", 2, "transito", "Amarração de cargas", [36], "Nos veículos com carroceria aberta, os dispositivos de amarração devem ser tensionados pelo lado externo das guardas laterais, independentemente do espaço interno ocupado pela carga na carroceria, como mostram as figuras a seguir.\n\n[As figuras da prova não foram reproduzidas aqui.]", "E", "Na carroceria aberta com espaço livre, o tensionamento é feito pelo lado interno das guardas laterais. Pelo lado externo só se admite quando a carga ocupa todo o espaço interno. O “independentemente do espaço” torna o item errado.", "Na época valia a Resolução 552/2015, hoje revogada pela Resolução CONTRAN 945/2022. A resposta continua a mesma."],
  [84, "", 2, "transito", "Amarração de cargas", [36], "Tanto em veículos do tipo baú frigorífico (como o da figura 1A9-I a seguir) como em veículos do tipo baú lonado (como o da figura 1A9-II a seguir), é opcional a existência de pontos de amarração internos para a carga transportada.\n\n[As figuras da prova não foram reproduzidas aqui.]", "E", "No baú frigorífico ou isotérmico, as próprias paredes contêm a carga, e os pontos internos são opcionais. No baú lonado, a lona não serve de contenção: os pontos de amarração são obrigatórios. O item erra ao tratar os dois da mesma forma.", "Na época valia a Resolução 552/2015, hoje revogada pela Resolução CONTRAN 945/2022. A resposta continua a mesma."],
  [86, "", 2, "transito", "Motocicletas (capacete)", [37], "É permitido que motociclista levante a viseira do capacete enquanto o veículo conduzido estiver parado, aguardando a travessia de pedestres diante de semáforo.", "C", "Com a moto parada, o condutor pode levantar a viseira por completo. A viseira abaixada é exigida com o veículo em movimento.", "A norma da época (Resolução 453/2013) foi substituída pela Resolução CONTRAN 940/2022, que mantém a regra."],
  [87, "", 2, "transito", "Motocicletas (capacete)", [37], "Situação hipotética: Em operação de fiscalização em uma rodovia federal, a equipe da PRF verificou que o condutor de um quadriciclo não fazia uso do capacete. O policial que abordou o condutor o liberou, considerando que o uso de capacete pelo condutor desse tipo de veículo se restringe à condução em vias urbanas pavimentadas. Assertiva: Nessa situação, foram adequadas as condutas do policial e do condutor.", "E", "O capacete é obrigatório para condutor e passageiro de motocicleta, motoneta, ciclomotor, triciclo e quadriciclo motorizado, em qualquer via, não só nas urbanas. O policial devia autuar.", ""],
  [88, "", 2, "transito", "Processo administrativo (notificação)", [38], "Situação hipotética: Ao abordar um veículo em rodovia federal, o policial rodoviário federal constatou que o condutor, que era o proprietário do veículo, dirigia sem utilizar o cinto de segurança. O policial lavrou o auto de infração, que continha a assinatura do condutor e especificava o prazo para apresentação da defesa da autuação. Assertiva: Nessa situação, fica a PRF dispensada de expedir a notificação da autuação ao proprietário do veículo.", "C", "Se o auto de infração é assinado pelo condutor que também é o proprietário e já traz o prazo para a defesa, ele vale como notificação da autuação, e a PRF não precisa expedir outra (art. 280, VI, e art. 281-A do CTB).", ""],
  [89, "", 2, "transito", "Receita das multas", [38], "As receitas oriundas das multas aplicadas pela PRF serão repassadas ao DNIT, órgão executivo rodoviário com circunscrição sobre as rodovias federais.", "E", "A receita das multas fica com o órgão que as aplica e vai só para os fins do art. 320 do CTB, como sinalização, engenharia de tráfego, policiamento, fiscalização e educação de trânsito, com 5% para um fundo nacional. Não há repasse ao DNIT.", ""],
  [90, "", 2, "transito", "Processo administrativo (suspensão)", [38], "Situação hipotética: Policial rodoviário federal, ao flagrar o condutor de um veículo dirigindo alcoolizado, o que ficou comprovado pelo teste de etilômetro, lavrou o competente auto de infração de trânsito. Assertiva: Nessa situação, a própria PRF aplicará ao condutor infrator a penalidade de suspensão do direito de dirigir, assegurando-lhe a ampla defesa, o contraditório e o devido processo legal.", "E", "Pela lei da época, a PRF aplicava a multa e as medidas administrativas, e a suspensão do direito de dirigir era aplicada pelo órgão de trânsito do estado (DETRAN), em processo próprio (art. 22, II, e art. 265).", "Desde 12/4/2021 (Lei 14.071/2020), quando a infração já prevê a suspensão, como dirigir sob influência de álcool, o processo de suspensão corre junto com o da multa, no órgão que aplica a multa (art. 261, § 10). Hoje a própria PRF aplicaria a suspensão, e o item seria Certo. O gabarito oficial foi mantido."],
  [92, "", 3, "adm", "Atos administrativos (motivo)", [39], "Tanto a inexistência da matéria de fato quanto a sua inadequação jurídica podem configurar o vício de motivo de um ato administrativo.", "C", "Pela Lei da Ação Popular (Lei 4.717/1965, art. 2.º, parágrafo único, d), há vício de motivo quando a matéria de fato ou de direito em que o ato se baseia é materialmente inexistente ou juridicamente inadequada ao resultado.", ""],
  [93, "", 3, "adm", "Poder de polícia", [40], "Constitui poder de polícia a atividade da administração pública ou de empresa privada ou concessionária com delegação para disciplinar ou limitar direito, interesse ou liberdade, de modo a regular a prática de ato em razão do interesse público relativo à segurança.", "E", "O conceito legal (CTN, art. 78) liga o poder de polícia à administração pública. Ele não é delegado a empresas privadas comuns nem a qualquer concessionária.", "Em 2020, o STF (Tema 532) admitiu que estatais de direito privado que prestam serviço público em regime não concorrencial exerçam as fases de consentimento, fiscalização e sanção. Mesmo assim, o item continua errado ao incluir empresa privada e concessionária em geral."],
  [94, "", 3, "adm", "Abuso de poder", [40], "O abuso de poder, que inclui o excesso de poder e o desvio de finalidade, não decorre de conduta omissiva de agente público.", "E", "O abuso de poder (excesso de poder ou desvio de finalidade) também pode vir de omissão: quando o agente deixa de agir quando devia.", ""],
  [95, "", 3, "adm", "Responsabilidade civil do Estado", [40], "A responsabilidade civil do Estado por ato comissivo é subjetiva e baseada na teoria do risco administrativo, devendo o particular, que foi a vítima, comprovar a culpa ou o dolo do agente público.", "E", "Por ato comissivo, a responsabilidade do Estado é objetiva (CF, art. 37, § 6.º): a vítima não precisa provar culpa nem dolo do agente, só o dano e o nexo com a conduta.", ""],
  [96, "", 3, "con", "Direitos fundamentais (requisição)", [41], "Em caso de iminente perigo público, autoridade pública competente poderá usar a propriedade particular, desde que assegure a consequente indenização, independentemente da comprovação da existência de dano, que, nesse caso, é presumido.", "E", "Na requisição por iminente perigo público, a indenização é posterior e só existe se houver dano (CF, art. 5.º, XXV). O dano não é presumido.", ""],
  [97, "", 3, "con", "Segurança pública (PRF)", [41], "A competência da PRF, instituição permanente, organizada e mantida pela União, inclui o patrulhamento ostensivo das rodovias e das ferrovias federais.", "E", "Pelo art. 144, § 2.º, da CF, a PRF faz o patrulhamento ostensivo das rodovias federais. As ferrovias federais ficam com a Polícia Ferroviária Federal (§ 3.º).", "A PEC 18/2025 (PEC da Segurança Pública), aprovada pelo Senado em 3/11/2026 e ainda à espera de promulgação, estende a atuação da PRF às ferrovias e hidrovias federais. Se for promulgada, este item terá de ser revisto."],
  [98, "", 3, "con", "Direitos políticos e servidores", [41], "Policial rodoviário federal com mais de dez anos de serviço pode candidatar-se ao cargo de deputado federal, devendo, no caso de ser eleito, passar para inatividade a partir do ato de sua diplomação.", "E", "O policial rodoviário federal é servidor civil. Eleito deputado federal, ele fica afastado do cargo (CF, art. 38, I). A regra dos dez anos com inatividade a partir da diplomação vale para o militar (art. 14, § 8.º, II).", ""],
  [99, "", 3, "con", "Direitos do preso", [41], "São constitucionalmente assegurados ao preso o direito à identificação dos agentes estatais responsáveis pela sua prisão e o direito de permanecer em silêncio.", "C", "A CF garante ao preso saber quem são os responsáveis pela prisão ou pelo interrogatório (art. 5.º, LXIV) e o direito de ficar calado (art. 5.º, LXIII).", ""],
  [100, "", 3, "con", "Segurança viária", [41], "A segurança viária compreende a educação, a engenharia e a fiscalização de trânsito, vetores que asseguram ao cidadão o direito à mobilidade urbana eficiente.", "C", "Pelo art. 144, § 10, I, da CF (EC 82/2014), a segurança viária compreende a educação, a engenharia e a fiscalização de trânsito, além de outras atividades que asseguram ao cidadão a mobilidade urbana eficiente.", ""],
  [101, "", 3, "penal", "Descaminho", [42, 43], "A conduta do motorista configura crime de descaminho em sua forma consumada, ainda que não tenha havido constituição definitiva do crédito tributário e a ocorrência de efetivo prejuízo ao erário.", "C", "O descaminho é crime formal: consuma-se com a entrada da mercadoria sem pagar os tributos. Não depende da constituição definitiva do crédito tributário (a Súmula Vinculante 24 não se aplica a ele).", ""],
  [102, "", 3, "penal", "Facilitação de contrabando ou descaminho", [42, 43], "Caso fique comprovada a participação do servidor público na conduta delituosa, ele responderá pelo delito de descaminho em sua forma qualificada: ela tinha o dever funcional de prevenir e de reprimir o crime.", "E", "O servidor que, violando o dever funcional, facilita o descaminho comete crime próprio: facilitação de contrabando ou descaminho (CP, art. 318), com reclusão de 3 a 8 anos. Não existe “descaminho qualificado” por esse motivo.", ""],
  [103, "", 3, "proc", "Prisão em flagrante", [44, 45], "De acordo com a classificação doutrinária dominante, a situação configura hipótese de flagrante presumido ou ficto.", "C", "O preso foi encontrado, logo depois do crime, com a arma que faz presumir ser ele o autor (CPP, art. 302, IV). A doutrina chama isso de flagrante presumido ou ficto.", ""],
  [104, "", 3, "proc", "Prisão em flagrante", [44, 45], "Quanto ao sujeito ativo da prisão, o flagrante narrado é classificado como obrigatório, hipótese em que a ação de prender e as eventuais consequências físicas dela advindas em razão do uso da força se encontram abrigadas pela excludente de ilicitude denominada exercício regular de direito.", "E", "Para a autoridade policial e seus agentes, prender em flagrante é obrigação (CPP, art. 301). Por isso a excludente é o estrito cumprimento do dever legal. O exercício regular de direito é do flagrante facultativo, feito por qualquer pessoa.", ""],
  [105, "", 3, "proc", "Auto de prisão em flagrante", [44, 45], "Durante o procedimento de lavratura do auto de prisão em flagrante pela autoridade policial competente, o policial rodoviário responsável pela prisão e condução do preso deverá ser ouvido logo após a oitiva das testemunhas e o interrogatório do preso.", "E", "Pelo art. 304 do CPP, a autoridade ouve primeiro o condutor, depois as testemunhas e, por fim, interroga o preso. O condutor não fica para depois.", ""],
  [106, "", 3, "penal", "Princípio da legalidade", [46, 47], "A norma penal deve ser instituída por lei em sentido estrito, razão por que é proibida, em caráter absoluto, a analogia no direito penal, seja para criar tipo penal incriminador, seja para fundamentar ou alterar a pena.", "E", "A analogia é proibida para prejudicar o réu (criar crime ou agravar pena), mas é aceita em favor dele (in bonam partem). A proibição não é absoluta.", ""],
  [107, "", 3, "penal", "Princípio da legalidade", [46, 47], "O presidente da República, em caso de extrema relevância e urgência, pode editar medida provisória para agravar a pena de determinado crime, desde que a aplicação da pena agravada ocorra somente após a aprovação da medida pelo Congresso Nacional.", "E", "A CF proíbe medida provisória sobre direito penal (art. 62, § 1.º, I, b). Nem a aprovação posterior pelo Congresso torna válida a criação de crime por medida provisória.", ""],
  [108, "", 3, "penal", "Tráfico de pessoas", [48, 49], "A conduta do motorista do veículo se amolda ao tipo penal do tráfico de pessoas, em sua forma consumada, incidindo, nesse caso, causa de aumento de pena, em razão de as vítimas serem adolescentes.", "C", "Transportar pessoas mediante grave ameaça para fins de exploração sexual é tráfico de pessoas (CP, art. 149-A, V). O crime é formal: consuma-se com o transporte, sem precisar da exploração. Contra adolescentes, a pena aumenta de 1/3 até a metade (§ 1.º, II).", ""],
  [110, "", 3, "con", "Inviolabilidade do domicílio", [50], "A entrada forçada em determinado domicílio é lícita, mesmo sem mandado judicial e ainda que durante a noite, caso esteja ocorrendo, dentro da casa, situação de flagrante delito nas modalidades próprio, impróprio ou ficto.", "C", "A CF permite entrar na casa sem mandado, de dia ou de noite, em caso de flagrante delito (art. 5.º, XI), e isso vale para qualquer modalidade de flagrante.", ""],
  [111, "", 3, "especial", "Estatuto do Desarmamento", [51], "Em uma operação da PRF, foram encontradas, no veículo de Sandro, munições de arma de fogo de uso permitido e, no veículo de Eurípedes, munições de uso restrito. Nenhum deles tinha autorização para o transporte desses artefatos. Nessa situação, considerando-se o previsto no Estatuto de Desarmamento, Sandro responderá por infração administrativa e Eurípedes responderá por crime.", "E", "Transportar munição sem autorização é crime nos dois casos: de uso permitido (Lei 10.826/2003, art. 14) e de uso restrito (art. 16). Sandro também comete crime.", ""],
  [112, "", 3, "especial", "Exploração sexual de adolescente", [51], "João foi flagrado, em operação da PRF, submetendo uma adolescente a exploração sexual em rodovia federal. Nessa situação, João poderá não responder pelo crime se comprovar o consentimento da menor.", "E", "Submeter adolescente à exploração sexual é crime (ECA, art. 244-A; CP, art. 218-B), e o consentimento da vítima não afasta o crime.", ""],
  [114, "", 3, "especial", "Tráfico de pessoas (política nacional)", [52], "A Política Nacional de Enfrentamento ao Tráfico de Pessoas é coordenada por vários órgãos da Presidência da República.", "C", "Na época da prova, a política era coordenada pela Coordenação Tripartite (Decreto 7.901/2013): Ministério da Justiça e duas secretarias da Presidência da República, a de Políticas para as Mulheres e a de Direitos Humanos. Por isso a banca deu Certo.", "O Decreto 7.901/2013 foi revogado em 2019 (Decreto 9.833/2019), e aquelas secretarias deixaram a Presidência. O gabarito oficial foi mantido."],
  [115, "", 3, "especial", "Crimes ambientais", [52], "Situação hipotética: João foi autuado por policial rodoviário federal, por supostamente ter praticado conduta prevista como crime contra a fauna. Assertiva: Nessa situação, João necessariamente responderá pela conduta praticada.", "E", "Ser autuado não quer dizer que haverá condenação. A conduta pode não ser crime (a Lei 9.605/1998, art. 37, exclui o abate em certas situações), e há saídas como a transação penal. O “necessariamente” torna o item errado.", ""],
  [116, "", 3, "dh", "Teoria geral dos direitos humanos", [53], "As pessoas naturais que violam direitos humanos continuam a gozar da proteção prevista nas normas que dispõem sobre direitos humanos.", "C", "Pela universalidade, todas as pessoas têm direitos humanos, inclusive quem os viola.", ""],
  [117, "", 3, "dh", "Responsabilidade do Estado", [53], "Apenas por atos de seus agentes o Estado pode ser responsabilizado por violação de direitos humanos reconhecidos na Convenção Americana de Direitos Humanos.", "E", "O Estado também responde por omissão: quando deixa de prevenir, investigar ou punir violações cometidas por particulares (falta de devida diligência). Não é “apenas” por atos dos seus agentes.", ""],
  [118, "", 3, "dh", "Teoria geral dos direitos humanos", [53], "Todos os direitos humanos foram afirmados em um único momento histórico.", "E", "Pela historicidade, os direitos humanos foram afirmados aos poucos, em vários momentos da história (as “gerações” ou dimensões de direitos).", ""],
  [119, "", 3, "dh", "Tratados de direitos humanos", [54], "Conforme a maneira como são internalizados, os tratados internacionais sobre direitos humanos podem receber status normativo-hierárquico constitucional ou legal.", "E", "Para o STF (RE 466.343), o tratado de direitos humanos aprovado pelo rito do art. 5.º, § 3.º, tem status constitucional; os demais têm status supralegal, e não apenas legal.", ""],
  [120, "", 3, "dh", "Tratados de direitos humanos", [54], "A hierarquia constitucional dos tratados internacionais de direitos humanos depende de sua aprovação por três quintos dos membros de cada casa do Congresso Nacional.", "C", "Pelo art. 5.º, § 3.º, da CF, o tratado de direitos humanos equivale a emenda constitucional se for aprovado em cada Casa do Congresso, em dois turnos, por três quintos dos membros.", ""],
];
